/*
 * A266982  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 81" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A266982
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(0) = 1; for n > 0, a(n) = (∑_{i=1}^{n-2} ⌊(n-2)/i⌋) mod 2
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Handle the offset and small indices quickly */
    if (n == 0)
        return (seq_t)1;
    if (n <= 2) /* n = 1 or 2 → sum over an empty range → 0 mod 2 */
        return (seq_t)0;

    idx_t m = n - 2;          /* m = n - 2 ≥ 1        */
    seq_t parity = 0;         /* we only care about parity */

    for (idx_t i = 1; i <= m; ++i)
    {
        /* floor(m / i) is m / i because of integer division */
        parity ^= (m / i) & (seq_t)1;   /* XOR the parity of each term */
    }

    return parity;
}
